/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var format = require( '@stdlib/string/format' );

/**
* Method to provide teh safe row number.
* Note: This method provide the row number which present in plot area and does'nt collide with the axis labels and axis.
*
* @private
* @name getSafeRow
* @param {number} pos - position
* @throws {TypeError} - must be a valid position respective to the plot area
* @returns {void}
*/
function getSafeRow( pos ) {
	var row;

	// Note: If axis are there then they will acquired there 1 respective space so position should always need to valid according to remaining space
	if ( pos < 0 || pos >= ( this.plotAreaHeight - this.yAxis - this.zAxis ) ) {
		throw new TypeError( format( 'invalid option. `%s` must be valid respective to the plot are remaining space. Option: `%s`.', 'getSafeRow', pos ) );
	}
	row = this.plotArea.y + pos;
	if ( pos >= this.yAxisPos ) {
		row = pos + this.yTicsLabelSpace + 1;
	}

	return row;
}

module.exports = getSafeRow;
